insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-elitone-device', 'Elitone (Stress & Mixed Incontinence)', 'Elitone', 'incontinence', 'physical', 'An FDA-cleared, external at-home electrical stimulation device for stress and mixed urinary incontinence that strengthens the pelvic floor — no internal probe required, unlike many competitors.', '$149', 'https://elitone.com/wp-content/uploads/2021/05/SUI-Hero-2-1200x1000-AVIF.avif', 'https://elitone.com/product/elitone/', '["incontinence","pelvic-floor","fda-cleared"]'::jsonb, '["bladder-control","pelvic-floor-strengthening"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-cleared device (regulatory clearance for safety/equivalence, not an independently verified efficacy claim).","materials":"External electrode pad; see brand site for full device specs.","recalls":"No recalls found.","sideEffects":"Standard precautions for electrical stimulation devices apply (not for use with a pacemaker or during pregnancy without clinician guidance) — check the brand''s full contraindication list before use."}'::jsonb, 'Uses external electrical muscle stimulation (not an internal probe) to strengthen the pelvic floor for stress/mixed urinary incontinence — the mechanism is well-established in pelvic floor physical therapy generally. No independent (non-brand) clinical study of this exact device was found.', null, 'The brand states clinical study support for reducing leaks; no independent, third-party peer-reviewed study of this specific device was found. Pelvic floor muscle stimulation as a general modality for stress incontinence has real published evidence at the category level.', 'brand', 'Sourced from Elitone''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-lansinoh-lanolin-cream', 'Lansinoh Lanolin Nipple Cream', 'Lansinoh', 'postpartum', 'physical', 'Lansinoh''s 100% natural, ultra-purified lanolin nipple cream for breastfeeding — the brand states it does not need to be removed before nursing.', '$12.42', 'https://lansinoh.com/cdn/shop/files/US_June2026_NewCartons-Batch2_PDP_Lanolin-40g.png?v=1784647853', 'https://lansinoh.com/collections/nipple-creams-care/products/lanolin-nipple-cream', '["lactation","postpartum","nipple-care"]'::jsonb, '["breastfeeding-support"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic/topical emollient; not an FDA-evaluated drug.","materials":"100% purified lanolin.","recalls":"No recalls found.","sideEffects":"Rare lanolin sensitivity/allergy is the main thing to watch for."}'::jsonb, 'Lanolin is a widely used, well-established emollient for nipple soreness/cracking during breastfeeding; the "no need to remove before nursing" claim is standard for medical-grade purified lanolin products in this category, not unique to this brand.', null, 'Lanolin for nipple care has real category-level evidence and decades of clinical use in lactation support; no independent study of this specific product formulation was found.', 'brand', 'Sourced from Lansinoh''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-eli-health-cortisol', 'Eli Health Cortisol Test', 'Eli Health', 'hormone-monitoring', 'physical', 'An at-home saliva cortisol test paired with Eli Health''s app, giving results in about 20 minutes; the brand positions it as a wellness-tracking tool, not a diagnostic device.', '$199', 'https://eli.health/cdn/shop/files/educationalcortisolpdp-image1.png?v=1782501783&width=1200', 'https://eli.health/products/cortisol', '["hormone-monitoring","cortisol","at-home-test"]'::jsonb, '["hormone-tracking","stress-monitoring"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Consumer wellness test; not positioned by the brand as a diagnostic device.","materials":"Saliva collection kit; see brand site for full specs.","recalls":"No recalls found.","sideEffects":"None specific to the test itself; a single-timepoint result should not replace clinical evaluation for suspected adrenal/hormonal disorders."}'::jsonb, 'Salivary cortisol testing is a real, established method used clinically (e.g. for diurnal cortisol curves), though at-home single-timepoint consumer tests are a wellness-tracking tool, not a diagnostic replacement for a clinical workup. The brand states a 97% accuracy figure vs. lab methods; that is a brand claim, not independently verified here.', null, 'No independent, third-party study of this specific device''s accuracy was found; the accuracy figure is the brand''s own claim. Salivary cortisol testing as a method has real clinical-literature support at the category level.', 'brand', 'Sourced from Eli Health''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-pips-postpartum-ice-panty', 'PIPs Postpartum Ice Panty Package', 'PIPs Comfort Care', 'postpartum', 'physical', 'A boy-short style panty with a built-in pocket that holds an ice pack and a sanitary pad together, designed by an OB/GYN for perineal pain relief and swelling after vaginal childbirth.', '$34.95', 'https://www.pipscomfortcare.com/uploads/9/6/3/0/9630913/pips-cover-shot.jpg?250', 'https://www.pipscomfortcare.com/post-partum-ice-panty.html', '["postpartum","perineal-care","ice-therapy"]'::jsonb, '["postpartum-recovery","pain-relief"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not a medical device; a garment for holding standard cold-therapy items.","materials":"See brand site for fabric details.","recalls":"No recalls found.","sideEffects":"Standard cold-therapy precautions apply — avoid prolonged direct skin contact without a barrier, follow standard icing guidance (e.g. 15-20 minutes on/off)."}'::jsonb, 'Combines cold therapy — a well-established approach for reducing perineal swelling and pain after vaginal delivery — with a wearable garment that holds both an ice pack and a pad in place, more practical than loose ice packs in the first days postpartum. Designed by an OB/GYN specifically for this purpose.', null, 'Cold therapy for perineal pain/swelling after vaginal birth is a widely recommended, low-risk postpartum practice; no independent clinical study of this specific product was found — it''s a practical delivery mechanism for an accepted technique, not a proprietary clinical innovation with its own trial data.', 'brand', 'Sourced from PIPs Comfort Care''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-altrocare-postpartum-binder', 'AltroCare Postpartum Abdominal Binder', 'AltroCare', 'postpartum', 'physical', 'An adjustable compression abdominal binder for postpartum and post-surgical recovery, from a women-owned company manufacturing recovery products in the US.', 'From $18.99', 'https://altrocare.com/cdn/shop/files/Main_new_v3.png?v=1755548184', 'https://www.altrocare.com/products/postpartum-abdominal-binder', '["postpartum","compression","recovery"]'::jsonb, '["postpartum-recovery"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not a medical device; a compression garment.","materials":"See brand site for fabric/compression details.","recalls":"No recalls found.","sideEffects":"Anyone with a C-section incision should confirm with their own surgeon how soon and how tightly a binder is appropriate."}'::jsonb, 'Abdominal binders provide external compression many postpartum patients find supportive for core stability and comfort while abdominal muscles and any C-section incision heal, though independent evidence that binders meaningfully speed physical recovery (vs. comfort alone) is mixed.', null, 'Postpartum abdominal binders are widely used and recommended by some OB providers for comfort/support, but independent clinical evidence that they meaningfully accelerate core-muscle recovery is mixed rather than strongly established. No independent study of this specific product was found.', 'brand', 'Sourced from AltroCare''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-tampontribe-organic-tampons', 'Tampon Tribe Organic Tampons', 'Tampon Tribe', 'tampon', 'physical', '100% certified organic cotton tampons with plastic-free, compostable packaging, from a women- and minority-owned period care brand. Available in Regular, Super, and Super Plus.', '$10.60', 'https://tampontribe.com/cdn/shop/products/organic-tampons-4630724.png?v=1783121136&width=1946', 'https://www.tampontribe.com/products/tampons', '["organic","plastic-free","cotton"]'::jsonb, '["period-care"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"OTC menstrual product, FDA-regulated as a medical device class.","materials":"100% certified organic cotton.","recalls":"No recalls found.","sideEffects":"Change every 4-8 hours, never beyond 8 hours, to reduce TSS risk — standard guidance for any tampon."}'::jsonb, '100% organic cotton tampons are a reasonable choice for anyone wanting to avoid rayon blends, synthetic fibers, or fragrance, and are generally considered as safe as any FDA-regulated tampon when used per standard guidance. No brand-specific safety concerns found.', null, 'No independent clinical study of this specific product was found; 100% organic cotton tampons as a category are well-established and widely sold, with the documented benefit being avoidance of synthetic materials rather than superior absorption or leak protection.', 'brand', 'Sourced from Tampon Tribe''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true,"stockNote":"Listed as sold out on the brand''s own site as of 2026-08-25 — verify current stock before promoting."}'::jsonb),
  ('p-proov-complete-testing-system', 'Proov Complete Fertility Testing System', 'Proov', 'fertility', 'physical', 'An at-home hormone test kit measuring LH, PdG (a progesterone metabolite), and FSH across a cycle to identify fertile days and confirm successful ovulation.', '$99.99', 'https://cdn.shopify.com/s/files/1/0038/5417/2275/files/Complete-PDP-HSA_FSA_3.png?v=1767377529', 'https://proovtest.com/products/complete-testing-system', '["fertility","ovulation","hormone-testing","pdg"]'::jsonb, '["fertility-tracking","hormone-monitoring"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Consumer at-home hormone test.","materials":"See brand site for full kit contents.","recalls":"No recalls found.","sideEffects":"None specific to the test itself; does not replace a real fertility workup for suspected PCOS, thyroid dysfunction, or recurrent miscarriage, which needs a clinician and bloodwork."}'::jsonb, 'PdG (pregnanediol glucuronide) testing is a legitimate, clinically-used at-home proxy for confirming ovulation via a progesterone metabolite, and pairing it with LH and FSH gives a fuller picture than an ovulation-predictor kit alone. Appropriate for someone actively trying to conceive who wants confirmation of ovulation, not prediction alone.', null, 'Proov states the test is "99% accurate" and cites over 5,000 tracked conceptions — brand-reported figures, not an independent trial of this exact kit. PdG as a marker of confirmed ovulation is separately supported in reproductive-endocrinology literature; that general validity doesn''t itself confirm this specific kit''s real-world accuracy outside the brand''s own numbers.', 'brand', 'Sourced from Proov''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-momotaro-infection-defense-kit', 'Complete Infection Defense Kit', 'Momotaro Apotheca', 'intimate-care', 'physical', 'A 4-product botanical bundle the brand markets for supporting symptoms of BV, yeast infections, and vaginal pH imbalance through combined internal and external care.', '$150', 'https://cdn.shopify.com/s/files/1/1935/6703/files/infectiondefense_2026.webp?v=1778110385', 'https://momotaroapotheca.com/products/infection-defense-bundle', '["vaginal-health","bv","yeast-infection","ph-balance"]'::jsonb, '["vaginal-health"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Botanical/wellness products; not FDA-evaluated drugs.","materials":"See brand site for full bundle ingredient list.","recalls":"No recalls found.","sideEffects":"BV and yeast infections have different causes and need different treatment; self-treating either without a diagnosis risks masking or delaying real care."}'::jsonb, 'A naturopathic/herbalist bundling approach, not the same evidence tier as clinical antifungal/antibiotic treatment. Reasonable as a general vaginal-comfort/maintenance product absent an active suspected infection; anyone with active symptoms should get an actual diagnosis first.', null, 'No independent clinical study of this bundle or its ingredients for BV/yeast infection outcomes was found. Treat brand symptom-relief claims as unverified marketing, not clinical evidence.', 'brand', 'Sourced from Momotaro Apotheca''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-redmoon-vitex', 'Vitex (Vitex agnus-castus)', 'Red Moon Herbs', 'supplement', 'physical', 'A liquid vitex (chasteberry) extract marketed to support balanced hormones and healthy progesterone levels across menstrual and menopausal years — a well-known herbal supplement, not this brand''s proprietary invention.', '$16 (1 oz) up to $180 (16 oz)', 'https://cdn.shopify.com/s/files/1/1164/6886/products/Vitex.jpg?v=1664981813', 'https://redmoonherbs.com/products/vitex-vitex-agnus-castus', '["hormone-balance","pms","vitex","chasteberry"]'::jsonb, '["hormone-balance"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not evaluated by the FDA.","materials":"Vitex agnus-castus (chasteberry) liquid extract.","recalls":"No recalls found.","sideEffects":"Can interact with hormonal birth control and dopamine-affecting medications — worth a clinician check if on either."}'::jsonb, 'Vitex agnus-castus is a real, commonly studied herbal supplement with some clinical evidence for reducing PMS symptoms, though study quality/size varies. Generally taken long-term rather than for acute relief.', null, 'Some independent, peer-reviewed studies support vitex for PMS symptoms (mixed quality, mostly small trials) — a real, if modest, evidence base at the ingredient level, distinct from any brand-specific claim. No independent study of this specific extraction was found.', 'brand', 'Sourced from Red Moon Herbs'' own site and general herbal-medicine literature on vitex; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-partum-health', 'Partum Health', 'Partum Health', 'postpartum', 'digital', 'A concierge-style care marketplace matching pregnant and postpartum families with birth/postpartum doulas, lactation consultants, pelvic-floor physical therapists, and mental health providers. Currently serving Illinois, Michigan, and Texas.', 'Insurance/HSA often covers; contact for pricing', 'https://cdn.prod.website-files.com/628bfe13b58c3b10bf669d9f/63e43e0a72d04d1ec7b1a53e_opengraph.png', 'https://www.partumhealth.com/', '["doula","postpartum","lactation","pelvic-floor","mental-health"]'::jsonb, '["postpartum-recovery","mental-health","lactation-support"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Care-coordination service, not a regulated product.","materials":"n/a","recalls":"n/a","sideEffects":"n/a — outcomes depend on the individual practitioner matched, same as any care-marketplace model."}'::jsonb, 'Coordinating multiple real specialties (doula care, pelvic-floor PT, lactation, mental health, nutrition) under one intake is a genuinely useful model for postpartum recovery, since these needs often go unaddressed separately. Availability is geographically limited (IL/MI/TX as of 2026-08-25).', null, 'No independent outcomes study of Partum Health''s specific model was found — it''s a care-coordination service, not a product with its own efficacy claim. Effectiveness depends on each specialty''s own evidence base and the specific practitioner matched.', 'brand', 'Sourced from Partum Health''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
